#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = 1e18;

class mcf_graph_int_cost {
public:
    struct _edge {
        int to, rev;
        ll cap, cost;
        _edge() {}
        _edge(int to, int rev, ll cap, ll cost) : to(to), rev(rev), cap(cap), cost(cost) {}
    };

    struct edge {
        int from, to;
        ll cap, flow, cost;
        edge() {}
        edge(int from, int to, ll cap, ll flow, ll cost) : from(from), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    mcf_graph_int_cost(int n) : n(n) {
        g.resize(n);
    }

    int add_edge(int from, int to, ll cap, ll cost) {
        int m = pos.size();
        pos.push_back({from, (int)g[from].size()});
        g[from].push_back(_edge(to, (int)g[to].size(), cap, cost));
        g[to].push_back(_edge(from, (int)g[from].size() - 1, 0, -cost));
        return m;
    }

    edge get_edge(int i) {
        _edge &e = g[pos[i].first][pos[i].second];
        _edge &re = g[e.to][e.rev];
        return edge(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
    }

    vector<edge> edges() {
        vector<edge> ret;
        for (int i = 0; i < (int)pos.size(); i++) {
            _edge &e = g[pos[i].first][pos[i].second];
            _edge &re = g[e.to][e.rev];
            ret.push_back(edge(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost));
        }
        return ret;
    }

    vector<pair<ll, ll>> slope(int s, int t, ll flow_limit = INF) {
        dual.assign(n, 0);
        dist.assign(n, INF);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        ll flow = 0;
        ll cost = 0;
        ll prev_cost = -1;
        vector<pair<ll, ll>> result;
        result.push_back({flow, cost});
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            ll c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                _edge &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            ll d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) result.pop_back();
            result.push_back({flow, cost});
            prev_cost = cost;
        }
        return result;
    }

    pair<ll, ll> flow(int s, int t, ll flow_limit = INF) {
        auto res = slope(s, t, flow_limit);
        return res.back();
    }

private:
    int n;
    vector<pair<int, int>> pos;
    vector<vector<_edge>> g;
    vector<ll> dual, dist;
    vector<int> pv, pe;
    vector<bool> vis;

    bool _dual_ref(int s, int t) {
        dist.assign(n, INF);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            int v = pq.top().second;
            ll d = pq.top().first;
            pq.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)g[v].size(); i++) {
                _edge &e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                ll cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    ll a1, a2, a3, b1, b2, b3;
    cin >> a1 >> a2 >> a3;
    cin >> b1 >> b2 >> b3;

    mcf_graph_int_cost g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);
    for (int i = 1; i <= 3; i++) {
        for (int j = 4; j <= 6; j++) {
            ll cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, INF, cost);
        }
    }

    auto res = g.flow(0, 7);
    ll ans1 = res.second;
    ll ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

ll mod = 998244353;

ll inv_mod(ll n) {
    ll res = 1, e = mod - 2;
    while (e) {
        if (e & 1) res = (res * n) % mod;
        n = (n * n) % mod;
        e >>= 1;
    }
    return res;
}

vector<ll> factors(ll n) {
    vector<ll> v;
    for (ll i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            v.push_back(i);
            if (i * i != n) v.push_back(n / i);
        }
    }
    sort(v.begin(), v.end());
    return v;
}

ll match(ll a, ll b) {
    if (a == b) return 0;
    if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
    return -1;
}

ll give(vector<pair<ll,ll>>& l1, vector<pair<ll,ll>>& l2) {
    ll ans = 0;
    pair<ll,ll> curr1 = {0,0}, curr2 = {0,0};
    while (!l1.empty() || !l2.empty()) {
        if (curr1.first == 0 && !l1.empty()) { curr1 = l1.back(); l1.pop_back(); }
        if (curr2.first == 0 && !l2.empty()) { curr2 = l2.back(); l2.pop_back(); }
        if (curr1.first == 0 || curr2.first == 0) break;

        ll m = match(curr1.second, curr2.second);
        ll take = min(curr1.first, curr2.first);
        ans += max(0LL, take * m);

        if (curr1.first < curr2.first) {
            curr2.first -= curr1.first;
            curr1.first = 0;
        } else if (curr1.first > curr2.first) {
            curr1.first -= curr2.first;
            curr2.first = 0;
        } else {
            curr1.first = curr2.first = 0;
        }
    }
    return ans;
}

ll maximum(ll r1, ll s1, ll p1, ll r2, ll s2, ll p2) {
    return min(r1, s2) + min(s1, p2) + min(p1, r2);
}

ll minimum(ll n, ll r1, ll s1, ll p1, ll r2, ll s2, ll p2) {
    vector<pair<ll,ll>> base1 = {{r1,1}, {s1,2}, {p1,3}};
    vector<pair<ll,ll>> base2 = {{r2,1}, {s2,2}, {p2,3}};

    sort(base1.begin(), base1.end());
    sort(base2.begin(), base2.end());

    ll ans = 1e18;
    do {
        do {
            vector<pair<ll,ll>> l1 = base1;
            vector<pair<ll,ll>> l2 = base2;
            ans = min(ans, give(l1, l2));
        } while (next_permutation(base2.begin(), base2.end()));
    } while (next_permutation(base1.begin(), base1.end()));

    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll n; cin >> n;
    ll r1, s1, p1; cin >> r1 >> s1 >> p1;
    ll r2, s2, p2; cin >> r2 >> s2 >> p2;

    cout << minimum(n, r1, s1, p1, r2, s2, p2) << " " << maximum(r1, s1, p1, r2, s2, p2) << "\n";

    return 0;
}

