using namespace std;

int getWonMaxFast(vector<int>& inputA, vector<int>& inputB) {
    vector<int> wins(3, 0);
    for (int i = 0; i < 3; i++) {
        int good = (i + 1) % 3;
        wins[i] = min(inputA[i], inputB[good]);
        inputA[i] -= wins[i];
        inputB[good] -= wins[i];
    }
    return accumulate(wins.begin(), wins.end(), 0);
}

int getLostMaxFast(vector<int> inputA, vector<int> inputB) {
    vector<pair<int, int>> waysToLose = {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};

    int maxLost = 0;
    sort(waysToLose.begin(), waysToLose.end());

    do {
        vector<int> losts(3, 0);
        vector<int> inputACopy = inputA;
        vector<int> inputBCopy = inputB;

        for (auto& way : waysToLose) {
            int lost_add = min(inputACopy[way.first], inputBCopy[way.second]);
            inputACopy[way.first] -= lost_add;
            inputBCopy[way.second] -= lost_add;
            losts[way.first] += lost_add;
        }

        int lostSum = accumulate(losts.begin(), losts.end(), 0);
        if (lostSum > maxLost) {
            maxLost = lostSum;
        }
    } while (next_permutation(waysToLose.begin(), waysToLose.end()));

    return maxLost;
}

int main() {
    int n;
    cin >> n;

    vector<int> inputA(3), inputB(3);
    for (int i = 0; i < 3; i++) {
        cin >> inputA[i];
    }
    for (int i = 0; i < 3; i++) {
        cin >> inputB[i];
    }

    vector<int> inputA2 = inputA;
    vector<int> inputB2 = inputB;

    int won = getWonMaxFast(inputA, inputB);
    int lost = getLostMaxFast(inputA2, inputB2);

    cout << n - lost << " " << won << endl;

    return 0;
}

