using ll = long long;

const ll INF = (ll)1e18;
const ll MOD = (ll)1e9 + 7;
const double EPS = 1e-10;

struct Dinic {
    struct Edge {
        ll to, rev;
        ll cap;
        Edge(ll to, ll rev, ll cap) : to(to), rev(rev), cap(cap) {}
    };
    ll n;
    vector<vector<Edge>> links;
    vector<ll> depth, progress;
    vector<pair<ll, ll>> pos;

    Dinic(ll n) : n(n) {
        links.resize(n);
    }

    void add_edge(ll from, ll to, ll cap) {
        pos.emplace_back(from, (ll)links[from].size());
        links[from].emplace_back(to, (ll)links[to].size(), cap);
        links[to].emplace_back(from, (ll)links[from].size() - 1, 0);
    }

    void bfs(ll s) {
        depth.assign(n, -1);
        depth[s] = 0;
        queue<ll> q;
        q.push(s);
        while (!q.empty()) {
            ll v = q.front(); q.pop();
            for (auto &e : links[v]) {
                if (e.cap > 0 && depth[e.to] < 0) {
                    depth[e.to] = depth[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    ll dfs(ll v, ll t, ll f) {
        if (v == t) return f;
        for (ll &i = progress[v]; i < (ll)links[v].size(); ++i) {
            Edge &e = links[v][i];
            if (e.cap == 0 || depth[v] >= depth[e.to]) continue;
            ll d = dfs(e.to, t, min(f, e.cap));
            if (d == 0) continue;
            e.cap -= d;
            links[e.to][e.rev].cap += d;
            return d;
        }
        return 0;
    }

    ll flow(ll s, ll t) {
        ll flow = 0;
        while (true) {
            bfs(s);
            if (depth[t] < 0) return flow;
            progress.assign(n, 0);
            ll f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
    }
};

