#include <iostream>
#include <vector>
#include <map>
#include <cmath>
#include <algorithm>

using namespace std;

vector<int> primes;

void generate_primes() {
    for (int p = 2; p < 6000; ++p) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) primes.push_back(p);
    }
}

map<int, int> factor(int n) {
    map<int, int> d;
    for (int p : primes) {
        if (p * p > n) break;
        if (n % p == 0) {
            int c = 0;
            while (n % p == 0) {
                n /= p;
                ++c;
            }
            d[p] = c;
        }
    }
    if (n > 1) d[n] = 1;
    return d;
}

vector<long long> factors(int n) {
    map<int, int> d = factor(n);
    vector<long long> answer = {1};
    for (auto &entry : d) {
        int p = entry.first;
        int e = entry.second;
        vector<long long> a2;
        for (long long x : answer) {
            long long mult = 1;
            for (int i = 0; i <= e; ++i) {
                a2.push_back(x * mult);
                mult *= p;
            }
        }
        answer = a2;
    }
    return answer;
}

long long process(int n, long long m) {
    if (n == 0) return 0;
    if (n == 1) return 1 % m;
    if (n == 2) return 2 % m;
    vector<long long> f(n + 1);
    f[0] = 0;
    f[1] = 1 % m;
    f[2] = 2 % m;
    for (int i = 3; i <= n; ++i) {
        f[i] = (2 * f[i - 1]) % m;
        vector<long long> divs = factors(i);
        for (long long x : divs) {
            if (x >= 2 && x <= i) {
                long long diff = f[i / x] - f[(i - 1) / x];
                diff = (diff % m + m) % m;
                f[i] = (f[i] + diff) % m;
            }
        }
        f[i] %= m;
    }
    return f[n];
}

int main() {
    generate_primes();
    int n;
    long long m;
    cin >> n >> m;
    cout << process(n, m) << endl;
    return 0;
}

