using namespace std;
typedef long long ll;

bool is_good(vector<int>& f, int p, int k) {
    for (int i = 0; i < p; i++) {
        if (f[(k * i) % p] != (k * f[i]) % p)
            return false;
    }
    return true;
}

ll gen(vector<int>& f, int p, int k, int i) {
    if (i == p) {
        return is_good(f, p, k) ? 1 : 0;
    } else {
        ll ans = 0;
        for (int j = 0; j < p; j++) {
            f.push_back(j);
            ans += gen(f, p, k, i + 1);
            f.pop_back();
        }
        return ans;
    }
}

ll mod_pow(ll base, ll exp, ll mod) {
    ll res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

