typedef long long ll;

ll mod;
vector<vector<map<ll, ll>>> memo;

ll invnum(vector<int>& seq) {
    int N = seq.size();
    ll res = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            if (seq[i] > seq[j]) res++;
        }
    }
    return res;
}

ll naive(ll N, ll k, bool flag) {
    vector<int> p(N), q(N);
    for (int i = 0; i < N; i++) p[i] = i;
    ll res = 0;
    do {
        for (int i = 0; i < N; i++) q[i] = i;
        do {
            if ((flag && lexicographical_compare(p.begin(), p.end(), q.begin(), q.end())) || !flag) {
                if (invnum(p) - invnum(q) > k) res++;
            }
        } while (next_permutation(q.begin(), q.end()));
    } while (next_permutation(p.begin(), p.end()));
    return res;
}

ll solve(ll N, ll k, bool flag) {
    if (memo[N][flag].count(k)) return memo[N][flag][k];

    if (N == 1) {
        ll res;
        if (flag) res = 0;
        else {
            if (k < 0) res = 1;
            else res = 0;
        }
        memo[N][flag][k] = res;
        return res;
    }

    ll invnum_INF = N*(N-1)/2;
    if (k < -invnum_INF - 1) {
        ll res = solve(N, -invnum_INF - 1, flag);
        memo[N][flag][k] = res;
        return res;
    }
    if (k >= invnum_INF) {
        memo[N][flag][k] = 0;
        return 0;
    }

    ll res = 0;
    for (int delta = -(N-1); delta <= N-1; delta++) {
        if (flag && delta > 0) continue;
        ll wt = min((ll)(N - delta), (ll)(delta + N));
        res += solve(N-1, k - delta, (delta == 0) & flag) * wt;
        res %= mod;
    }
    memo[N][flag][k] = res % mod;
    return res % mod;
}

int main() {
    ll n;
    cin >> n >> mod;

    memo.resize(n+1);
    for (int i = 0; i <= n; i++) {
        memo[i][0] = map<ll,ll>();
        memo[i][1] = map<ll,ll>();
    }

    ll ans = solve(n, 0, 1) % mod;
    cout << ans << endl;

    return 0;
}

