    int i = 2;
    while (true) {
        if (i >= n * 2) {
            tree.assign(i, 0);
            break;
        } else {
            i *= 2;
        }
    }
}

void update(int i, int x) {
    i += tree.size() / 2;
    tree[i] = x;
    i /= 2;
    while (i > 0) {
        tree[i] = tree[2 * i] + tree[2 * i + 1];
        i /= 2;
    }
}

int get_sum(int s, int t) {
    s += tree.size() / 2;
    t += tree.size() / 2;
    int ans = 0;
    while (s <= t) {
        if (s % 2 == 1) {
            ans += tree[s];
            s++;
        }
        if (t % 2 == 0) {
            ans += tree[t];
            t--;
        }
        s /= 2;
        t /= 2;
    }
    return ans;
}

vector<int> prime_factorize(int n) {
    vector<int> ans;
    for (int i = 2; i * i <= n; ++i) {
        while (n % i == 0) {
            ans.push_back(i);
            n /= i;
        }
    }
    if (n > 1) ans.push_back(n);
    return ans;
}

