int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    int m = n * (n - 1) / 2;

    // dp[i][j][k] : i from 0..n, j from 0..m, k from 0..n
    vector<vector<vector<ll>>> dp(n + 1, vector<vector<ll>>(m + 1, vector<ll>(n + 1, 0)));
    dp[1][0][1] = 1;

    for (int i = 1; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; k <= n; ++k) {
                ll a = dp[i][j][k];
                if (a == 0) continue;
                // case l = i (insert i+1 at the end)
                dp[i + 1][j + i][i + 1] = (dp[i + 1][j + i][i + 1] + a) % mod;
                // case l from 0 to i-1
                for (int l = 0; l < i; ++l) {
                    dp[i + 1][j + i - 1 - l][k] = (dp[i + 1][j + i - 1 - l][k] + a) % mod;
                }
            }
        }
    }

    // S_dp[i][k][j] = prefix sum over j of dp[i][j][k]
    vector<vector<vector<ll>>> S_dp(n + 1, vector<vector<ll>>(n + 1, vector<ll>(m + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int k = 0; k <= n; ++k) {
            ll a = 0;
            for (int j = 0; j <= m; ++j) {
                a = (a + dp[i][j][k]) % mod;
                S_dp[i][k][j] = a;
            }
        }
    }

    // SS_dp[i][j][k] = prefix sum over k of S_dp[i][k][j]
    vector<vector<vector<ll>>> SS_dp(n + 1, vector<vector<ll>>(m + 1, vector<ll>(n + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            ll a = 0;
            for (int k = 0; k <= n; ++k) {
                a = (a + S_dp[i][k][j]) % mod;
                SS_dp[i][j][k] = a;
            }
        }
    }

    vector<ll> ANS(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        ll ans = (i * ANS[i - 1]) % mod;
        for (int k = 0; k <= n; ++k) {
            for (int j = 1; j <= m; ++j) {
                ll val = dp[i][j][k];
                if (val == 0) continue;
                // SS_dp[i][j-1][-1] is SS_dp[i][j-1][n]
                ll diff = (SS_dp[i][j - 1][n] - SS_dp[i][j - 1][k] + mod) % mod;
                ans = (ans + val * diff) % mod;
            }
        }
        ANS[i] = ans;
    }

    cout << ANS[n] << '\n';

    return 0;
