        long long mi = Ki[0].size();
        vector<vector<long long>> Si(ni, vector<long long>(mi, 0));
        for (long long j = 0; j < ni; j++) {
            Si[j][mi-1] = Ki[j][mi-1];
            for (long long k = mi-2; k >= 0; k--) {
                Si[j][k] = (Ki[j][k] + Si[j][k+1]) % M;
            }
        }
        for (long long j = 1; j < ni; j++) {
            for (long long k = 0; k < mi; k++) {
                Si[j][k] = (Si[j][k] + Si[j-1][k]) % M;
            }
        }

        long long si = 0;
        for (long long j = 1; j < ni; j++) {
            for (long long k = 0; k < mi-1; k++) {
                si = (si + (Ki[j][k] * Si[j-1][k+1]) % M) % M;
            }
        }

        long long c = C[i+1];
        si = (si * c) % M;
        s = (s + si) % M;
    }
    return s;
}

