    long long last_ans = 17;
    long long ans = 17;
    long long size = (n-1)*(n-2)/2 + 1;
    vector<vector<long long>> record(2, vector<long long>(size+1, 0));
    record[0][0] = 1;
    record[0][1] = 2;
    record[0][2] = 2;
    record[0][3] = 1;
    int inv = 1;
    for (long long m = 4; m < n; ++m) {
        long long tp_size = m*(m-1)/2;
        ans = (m+1) * last_ans % mod;
        long long tp = 0;
        for (long long i = 0; i < m; ++i) {
            tp += record[inv^1][i];
            record[inv][i] = tp % mod;
        }
        for (long long i = m; i <= tp_size/2; ++i) {
            tp += record[inv^1][i];
            tp -= record[inv^1][i-m];
            record[inv][i] = tp % mod;
        }
        for (long long i = 0; i <= tp_size/2; ++i) {
            record[inv][tp_size - i] = record[inv][i];
        }
        long long total = 0;
        for (long long i = 0; i < tp_size - 1; ++i) {
