#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<vector<long long>> dp;
int n, h;

long long t(int n, int h) {
    if (dp[n][h] == -1) {
        long long s = 0;
        for (int m = 1; m <= n; ++m) {
            long long part1 = 0;
            for (int i = 0; i < h; ++i) {
                part1 += t(n - m, i);
            }
            long long part2 = 0;
            for (int i = 0; i < h - 1; ++i) {
                part2 += t(m - 1, i);
            }
            s += t(m - 1, h - 1) * part1 + t(n - m, h - 1) * part2;
        }
        dp[n][h] = s;
    }
    return dp[n][h];
}

