using namespace std;

map<pair<int,int>, long long> all;
map<tuple<int,int,int>, long long> limit;
int n, m;

long long searchall(int lo, int hi) {
  if (lo == hi) return 1;
  if (all.find(make_pair(lo, hi)) != all.end()) return all[make_pair(lo, hi)];
  all[make_pair(lo, hi)] = 0;
  all[make_pair(lo, hi)] += searchall(lo+1, hi);
  all[make_pair(lo, hi)] += searchall(lo, hi-1);
  for (int i = lo+1; i < hi; i++) {
    all[make_pair(lo, hi)] += searchall(lo, i-1) * searchall(i+1, hi);
  }
  return all[make_pair(lo, hi)];
}

long long searchlimit(int lo, int hi, int depth) {
  if (lo == hi) {
    if (depth < m) return 1;
    else return 0;
  }
  auto key = make_tuple(lo, hi, depth);
  if (limit.find(key) != limit.end()) return limit[key];
  limit[key] = 0;
  limit[key] += searchlimit(lo+1, hi, depth+1);
  limit[key] += searchlimit(lo, hi-1, depth+1);
  for (int i = lo+1; i < hi; i++) {
    limit[key] += searchlimit(lo, i-1, depth+1) * searchlimit(i+1, hi, depth+1);
  }
  return limit[key];
}

int main() {
  string line;
  getline(cin, line);
  stringstream ss(line);
  ss >> n >> m;
  long long ret = searchall(1, n) - searchlimit(1, n, 1);
  cout << ret << endl;
  return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <cmath>

using namespace std;

int main() {
    string line;
    getline(cin, line);
    stringstream ss(line);
    int n, h;
    ss >> n >> h;

    const int MAX = 36;
    vector<vector<long long>> dp(MAX, vector<long long>(MAX, 0));
    dp[0][0] = 1;

    for (int nodes = 1; nodes < MAX; nodes++) {
        for (int minheight = 0; minheight <= nodes; minheight++) {
            for (int topnode = 1; topnode <= nodes; topnode++) {
                int left = topnode - 1;
                int right = nodes - topnode;
                long long total = dp[left][0] * dp[right][0];
                long long exclude = (dp[left][0] - dp[left][max(minheight - 1, 0)]) * 
                                    (dp[right][0] - dp[right][max(minheight - 1, 0)]);
                dp[nodes][minheight] += total - exclude;
            }
        }
    }

    cout << dp[n][h] << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

long long dp[35][35];

long long f(int n, int h) {
    if (n < 0 || h < 0) return 0;
    if (dp[n][h] != -1) return dp[n][h];
    if (n == 0) return 0;
    if (h == 0) return f(n, 1);

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += f(n - i - 1, 0) * f(i, h - 1);
        ans += f(n - i - 1, h - 1) * f(i, 0);
        ans -= f(n - i - 1, h - 1) * f(i, h - 1);
    }
    dp[n][h] = ans;
    return ans;
}

int main() {
    int n, h;
    cin >> n >> h;

    memset(dp, -1, sizeof(dp));
    dp[0][0] = 1;

    cout << f(n, h) << endl;
    return 0;
}

