        dp[0][j] = 1;
    }
    for (int i = 0; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int k = 0; k < i; k++) {
                dp[i][j] += dp[k][j - 1] * dp[i - 1 - k][j - 1];
            }
        }
    }
    long long result = dp[n][n] - (h > 0 ? dp[n][h - 1] : 0);
    cout << result << endl;
    return 0;
}

