#include <iostream>
#include <map>
#include <cmath>
using namespace std;

map<int, long long> tab1;
map<pair<int, int>, long long> tab2;

long long num1(int n) {
    if (n < 0) return 0;
    if (n < 2) return 1;
    if (tab1.find(n) == tab1.end()) {
        long long r = 0;
        for (int i = 0; i < n; i++) {
            r += num1(i) * num1(n - 1 - i);
        }
        tab1[n] = r;
    }
    return tab1[n];
}

long long num2(int n, int h) {
    if (n < 0 || h <= 0 || n >= (1 << (h - 1))) return 0;
    if (n < 2) return 1;
    if (n < h) return num1(n);
    auto key = make_pair(n, h);
    if (tab2.find(key) == tab2.end()) {
        long long r = 0;
        for (int i = 0; i < n; i++) {
            r += num2(i, h - 1) * num2(n - 1 - i, h - 1);
        }
        tab2[key] = r;
    }
    return tab2[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    cout << num1(n) - num2(n, h) << endl;
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, h;
    cin >> n >> h;
    vector<long long> s(n + 1, 1);
    vector<long long> t(n + 1, 1);

    for (int m = 1; m <= n; ++m) {
        long long sum = 0;
        for (int k = 0; k < m; ++k) {
            sum += s[m - 1 - k] * s[k];
        }
        s[m] = sum;
    }

    for (int j = 0; j < h; ++j) {
        vector<long long> new_t(n + 1);
        for (int m = 0; m <= n; ++m) {
            long long sum = 0;
            for (int k = 0; k < m; ++k) {
                sum += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
            }
            new_t[m] = sum;
        }
        t = new_t;
    }

    cout << t[n] << endl;
    return 0;
}
